#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int reg_no;
    char name[50];
    int marks;
} Student;

int main() {
    int N, K;
    Student *students = NULL;
    int total_students = 0;
    int total_marks = 0;
    int max_marks = -1;
    Student topper;

    if (scanf("%d", &N) != 1) return 0;

    students = (Student *)malloc(N * sizeof(Student));
    if (students == NULL) return 1;

    for (int i = 0; i < N; i++) {
        scanf("%d %s %d", &students[i].reg_no, students[i].name, &students[i].marks);
        total_marks += students[i].marks;
        total_students++;

        if (students[i].marks > max_marks) {
            max_marks = students[i].marks;
            topper = students[i];
        }
    }

    if (scanf("%d", &K) == 1) {
        students = (Student *)realloc(students, (N + K) * sizeof(Student));
        if (students == NULL) return 1;

        for (int i = N; i < N + K; i++) {
            scanf("%d %s %d", &students[i].reg_no, students[i].name, &students[i].marks);
            total_marks += students[i].marks;
            total_students++;

            if (students[i].marks > max_marks) {
                max_marks = students[i].marks;
                topper = students[i];
            }
        }
    }

    double average = (double)total_marks / total_students;

    printf("Total Students: %d\n", total_students);
    printf("Average Marks: %.2f\n", average);
    printf("Topper: %s\n", topper.name);
    printf("Register Number: %d\n", topper.reg_no);
    printf("Marks: %d\n", topper.marks);

    free(students);

    return 0;
}
